// Auto-assign IDs starting at 721, 4 rows per animal (da, nl, fr, es)
let rowId = 721;
const rows = [];

for (const a of animals) {
  const [animalId, da, nl, fr, es, da_d, nl_d, fr_d, es_d] = a;
  rows.push(`(${rowId++}, ${animalId}, 'da', '${q(da)}', '${q(da_d)}')`);
  rows.push(`(${rowId++}, ${animalId}, 'nl', '${q(nl)}', '${q(nl_d)}')`);
  rows.push(`(${rowId++}, ${animalId}, 'fr', '${q(fr)}', '${q(fr_d)}')`);
  rows.push(`(${rowId++}, ${animalId}, 'es', '${q(es)}', '${q(es_d)}')`);
}

// Output SQL
process.stdout.write('\n--\n-- Daten für Tabelle `animaltext` (da/nl/fr/es)\n-- ' + animals.length + ' Tiere × 4 Sprachen = ' + rows.length + ' Zeilen, IDs ' + 721 + '–' + (rowId-1) + '\n--\n\nINSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES\n');

for (let i = 0; i < rows.length; i++) {
  const isLast = i === rows.length - 1;
  process.stdout.write(rows[i] + (isLast ? ';\n' : ',\n'));
}

process.stderr.write('Generated ' + rows.length + ' rows, IDs 721–' + (rowId-1) + '\n');
